import{_ as h,C as r,o as n,c as e,a2 as i,b as c,w as a,a as g,E as s,a3 as d}from"./chunks/framework.O93z6AWZ.js";const v=JSON.parse('{"title":"Đề tài 1.1 — Suy tim tái nhập viện","description":"","frontmatter":{"title":"Đề tài 1.1 — Suy tim tái nhập viện"},"headers":[],"relativePath":"du_an/suy_tim.md","filePath":"du_an/suy_tim.md"}'),l={name:"du_an/suy_tim.md"};function u(m,t,b,p,y,_){const o=r("Mermaid");return n(),e("div",null,[t[1]||(t[1]=i('<h1 id="đe-tai-1-1-du-bao-nguy-co-đot-cap-suy-tim-mat-bu-tai-nhap-vien" tabindex="-1">Đề tài 1.1: Dự báo nguy cơ đợt cấp suy tim mất bù / tái nhập viện <a class="header-anchor" href="#đe-tai-1-1-du-bao-nguy-co-đot-cap-suy-tim-mat-bu-tai-nhap-vien" aria-label="Permalink to &quot;Đề tài 1.1: Dự báo nguy cơ đợt cấp suy tim mất bù / tái nhập viện&quot;">​</a></h1><p><strong>Nhóm đề tài:</strong> 1. Tín hiệu Y sinh &amp; Chuỗi Thời gian · <strong>Trạng thái:</strong> ✅ Y văn khởi động đầy đủ · ⏳ Workflow/timeline chi tiết theo mẫu chung bên dưới</p><div class="tip custom-block"><p class="custom-block-title">📥 Bộ tài liệu đầy đủ trên GitHub</p><p>Dữ liệu thô và mã nguồn chi tiết được lưu trữ <strong>Private</strong> trên kho GitHub của bộ môn (để đảm bảo sinh viên tự thực hiện). Sinh viên tham khảo thông tin mức độ cơ bản tại đây.</p></div><p>Đọc trước <strong><a href="/hmyt-book/du_an_mon_hoc">Khung Quản Lý &amp; Rubric</a></strong> — trang này chỉ cụ thể hóa cho riêng bài toán suy tim.</p><hr><h2 id="_1-phat-bieu-bai-toan" tabindex="-1">1. Phát biểu bài toán <a class="header-anchor" href="#_1-phat-bieu-bai-toan" aria-label="Permalink to &quot;1. Phát biểu bài toán&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Câu hỏi nghiên cứu</strong></td><td>Dự báo nguy cơ đợt cấp suy tim mất bù (ADHF) hoặc tái nhập viện 30 ngày từ dữ liệu chuỗi thời gian sinh hiệu hoặc bệnh án điện tử (EHR) bằng học máy</td></tr><tr><td><strong>Input (X)</strong></td><td>Đặc trưng lâm sàng bảng (tuổi, EF, eGFR, Kali máu, tiền sử...) <strong>hoặc</strong> chuỗi thời gian sinh hiệu liên tục (nhịp tim qua wearable)</td></tr><tr><td><strong>Output (Y)</strong></td><td>Nhị phân: tái nhập viện/tử vong trong cửa sổ thời gian xác định (30 ngày, hoặc cảnh báo sớm 21 ngày)</td></tr><tr><td><strong>Đối tượng</strong></td><td>Bệnh nhân suy tim (HFpEF/HFrEF), người cao tuổi, có thể kèm bệnh đồng mắc (T2DM)</td></tr><tr><td><strong>Dataset gợi ý</strong></td><td>MIMIC-III/IV (trích xuất chuỗi thời gian tim mạch), hoặc dữ liệu mô phỏng dựa trên registry công khai</td></tr><tr><td><strong>Thách thức đặc thù</strong></td><td>Tần số lấy mẫu không đồng đều của dữ liệu chuỗi thời gian y tế; cảnh báo sớm (Early Warning) trước 24-48h có giá trị lâm sàng cao hơn phát hiện muộn</td></tr></tbody></table><hr><h2 id="_2-y-van-khoi-đong-4-bai" tabindex="-1">2. Y văn khởi động (4 bài) <a class="header-anchor" href="#_2-y-van-khoi-đong-4-bai" aria-label="Permalink to &quot;2. Y văn khởi động (4 bài)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Citekey</th><th style="text-align:center;">Năm</th><th>DOI</th><th>Tóm tắt</th></tr></thead><tbody><tr><td><code>wang2025machine</code></td><td style="text-align:center;">2025</td><td><a href="https://doi.org/10.3389/fcvm.2025.1673159" target="_blank" rel="noreferrer">10.3389/fcvm.2025.1673159</a></td><td>Stacking Ensemble, N=870, AUC 0,867 — tái nhập viện 30 ngày (bệnh nhân T2DM+suy tim)</td></tr><tr><td><code>maesecalvo2026predicti</code></td><td style="text-align:center;">2026</td><td><a href="https://doi.org/10.1007/s11517-026-03657-2" target="_blank" rel="noreferrer">10.1007/s11517-026-03657-2</a></td><td>RF vs Logistic Regression, N~5.000 (registry 20 năm), AUC 0,812 vs 0,686</td></tr><tr><td><code>zhai2026explaina</code></td><td style="text-align:center;">2026</td><td><a href="https://doi.org/10.1186/s12911-026-03682-z" target="_blank" rel="noreferrer">10.1186/s12911-026-03682-z</a></td><td>XGBoost, N=1.308, AUC nội bộ 0,968 → <strong>AUC ngoại 0,718</strong> (cảnh báo overfitting rõ ràng — bài học quan trọng cho sinh viên về external validation)</td></tr><tr><td><code>vanes2025circadian</code></td><td style="text-align:center;">2025</td><td><a href="https://doi.org/10.1002/ehf2.15395" target="_blank" rel="noreferrer">10.1002/ehf2.15395</a></td><td><strong>LSTM thực sự trên chuỗi thời gian</strong> nhịp tim circadian (wearable), N=65, AUC~0,74, dự báo ADHF trước 21 ngày</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Bài học từ zhai2026explaina</p><p>AUC giảm mạnh từ 0,968 (nội bộ) xuống 0,718 (external validation trên eICU-CRD) — minh chứng cụ thể cho nguy cơ overfitting khi chỉ đánh giá nội bộ. Nhóm chọn đề tài này <strong>bắt buộc</strong> phải thiết kế external validation nếu có thể, hoặc ít nhất phân tích rõ giới hạn khi không có.</p></div><h3 id="so-đo-prisma" tabindex="-1">Sơ đồ PRISMA <a class="header-anchor" href="#so-đo-prisma" aria-label="Permalink to &quot;Sơ đồ PRISMA&quot;">​</a></h3>',12)),(n(),c(d,null,{default:a(()=>[s(o,{id:"mermaid-168",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A5%5B%22%C4%90%C3%A3%20x%C3%A1c%20minh%20Crossref%20tr%C6%B0%E1%BB%9Bc%20%C4%91%C3%B3%3A%203%22%5D%20--%3E%20TOTAL_ID%0A%20%20%20%20A6%5B%22WebSearch%20m%E1%BB%9Bi%20(l%E1%BA%A5p%20kho%E1%BA%A3ng%20tr%E1%BB%91ng%20LSTM)%3A%201%22%5D%20--%3E%20TOTAL_ID%5B%22T%E1%BB%95ng%20s%E1%BB%91%20b%E1%BA%A3n%20ghi%3Cbr%3EN%20%3D%204%22%5D%0A%20%20%20%20TOTAL_ID%20--%3E%20FINAL_INC%5B%22INCLUDE%20v%C3%A0o%20Evidence%20Matrix%3Cbr%3EN%20%3D%204%20(0%20EXCLUDE)%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[g(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=i('<hr><h2 id="_3-workflow-timeline" tabindex="-1">3. Workflow &amp; Timeline <a class="header-anchor" href="#_3-workflow-timeline" aria-label="Permalink to &quot;3. Workflow &amp; Timeline&quot;">​</a></h2><p>Áp dụng đúng <strong>workflow 7 giai đoạn</strong> và <strong>timeline 15 tuần</strong> trong khung chung (xem chi tiết đầy đủ tại trang <a href="/hmyt-book/du_an/roi_loan_nhip_tim">Đề tài 1.2 — Rối loạn nhịp tim</a> làm mẫu tham khảo cấu trúc). Lưu ý kỹ thuật đặc thù cho suy tim:</p><ul><li><strong>gd3-preprocessing:</strong> nếu dùng dữ liệu bảng (tabular/EHR) — xử lý dữ liệu khuyết bằng MICE/KNN Imputer chỉ fit trên Train; nếu dùng chuỗi thời gian sinh hiệu — chuẩn hóa windowing, xử lý tần số lấy mẫu không đều. Patient-level split bắt buộc theo mã bệnh nhân (không để 1 bệnh nhân xuất hiện ở cả Train và Test).</li><li><strong>gd4/gd5:</strong> Baseline Logistic Regression đối chứng bắt buộc (như <code>maesecalvo2026predicti</code> đã làm) trước khi thử RF/XGBoost/LSTM.</li><li><strong>gd6-evaluation-xai:</strong> dùng SHAP cho mô hình bảng (như <code>wang2025machine</code>, <code>zhai2026explaina</code>); nếu chọn hướng LSTM, cân nhắc attention weights hoặc SHAP-cho-chuỗi-thời-gian để giải thích.</li><li><strong>Khuyến nghị mở rộng:</strong> nếu nhóm có thời gian, thử nghiệm <strong>kết hợp</strong> đặc trưng bảng + chuỗi thời gian (multimodal) — đây là khoảng trống mà cả 4 bài khởi động chưa khai thác.</li></ul><hr><h2 id="_4-viec-con-ton-đong-tu-bao-cao-y-van" tabindex="-1">4. Việc còn tồn đọng (từ báo cáo y văn) <a class="header-anchor" href="#_4-viec-con-ton-đong-tu-bao-cao-y-van" aria-label="Permalink to &quot;4. Việc còn tồn đọng (từ báo cáo y văn)&quot;">​</a></h2><ol><li><code>comparator</code>/<code>validation_strategy</code> của <code>vanes2025circadian</code> cần đọc full-text để bổ sung.</li><li>Sinh viên tự bổ sung ≥6 bài để đạt yêu cầu ≥10 bài của Rubric Milestone 1.</li></ol><div class="warning custom-block"><p class="custom-block-title">Zero-Hallucination</p><p>Mọi trích dẫn phải khớp key có thật trong <code>.bib</code> đã xác minh DOI qua Crossref API. Vi phạm bị xử lý theo Phần IV.5 khung chung.</p></div>',8))])}const f=h(l,[["render",u]]);export{v as __pageData,f as default};
